theme.css:
/* theme: Double-Edged Signal | A day split between institutional cracks and market tremors — the page encodes Indonesia's broken alliance and Microsoft's outage as sobering red stalls against sliding amber numbers. */
/* mood: bad */
/* layout: hero=split; major-events=outline/grid-2; political-news=tile/stack; financial-news=stat/stack; tech-news=banner/grid-2; entertainment-news=numbered/grid-2; music-releases=plain/stack; stock-analysis=stat/grid-3; outlook=timeline/stack */

.diary-page {
  --paper: #1a090b;
  --paper-alt: #241014;
  --ink: #f5e8e4;
  --ink-soft: #d8b8b4;
  --muted: #b0857f;
  --accent: #ff5c5c;
  --accent-ink: #1a090b;
  --rule: #4a2428;
  --font-display: var(--ff-syne), sans-serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-space-grotesk), sans-serif;
}

/* Header: split with a hard, journalistic rule — the day's two fronts (politics and economy) face each other across a red seam */
.diary-page[data-hero="split"] .diary-hero {
  background: var(--paper-alt);
  border-bottom: 2px solid var(--accent);
  position: relative;
}

.diary-page[data-hero="split"] .diary-hero::after {
  content: "CRACKED / SLIDING";
  position: absolute;
  right: 1rem;
  bottom: 0.4rem;
  font-family: var(--font-ui);
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.22em;
  color: var(--accent);
  opacity: 0.85;
}

.diary-page .diary-kicker {
  color: var(--accent);
  letter-spacing: 0.28em;
  font-weight: 700;
}

.diary-page .diary-title {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: clamp(2.25rem, 5vw, 4.25rem);
  line-height: 0.98;
  letter-spacing: -0.02em;
  max-width: 14ch;
  text-transform: uppercase;
  color: var(--ink);
}

.diary-page .diary-summary {
  color: var(--ink-soft);
  border-left: 3px solid var(--accent);
  padding-left: 1rem;
}

.diary-page .diary-theme-note {
  color: var(--muted);
}

.diary-page .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
  border-radius: 0;
  font-weight: 700;
  letter-spacing: 0.08em;
}

/* Contents: a dark strip with red index numbers, like a stock ticker's warning line */
.diary-page .diary-toc {
  background: var(--paper);
  border-bottom: 1px solid var(--accent);
}

.diary-page .diary-toc-link,
.diary-page .diary-toc-top,
.diary-page .diary-toc-bottom {
  color: var(--muted);
}

.diary-page .diary-toc-link:hover,
.diary-page .diary-toc-top:hover,
.diary-page .diary-toc-bottom:hover,
.diary-page .diary-toc-link.is-active {
  color: var(--ink);
}

.diary-page .diary-toc-number {
  color: var(--accent);
  font-weight: 700;
}

@media (min-width: 1024px) {
  .diary-page .diary-toc-list {
    border-left-color: var(--rule);
  }
  .diary-page .diary-toc-link.is-active {
    border-left-color: var(--accent);
  }
}

/* Section heads: oversized, red, broken — the numbers lean like a cracked column */
.diary-page .diary-section {
  border-top: 1px solid var(--rule);
  padding-block: 2.5rem 1.5rem;
}

.diary-page .diary-section-head {
  align-items: baseline;
  gap: 0.75rem;
  margin-bottom: 1.5rem;
  border-bottom: 1px solid var(--accent);
  padding-bottom: 0.5rem;
}

.diary-page .diary-section-number {
  font-family: var(--font-display);
  font-size: 1.6rem;
  font-weight: 800;
  line-height: 1;
  color: var(--accent);
  letter-spacing: -0.03em;
  transform: rotate(-4deg);
  transform-origin: bottom left;
}

.diary-page .diary-section-title {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: clamp(1.6rem, 3vw, 2.2rem);
  text-transform: uppercase;
  letter-spacing: 0.01em;
  color: var(--ink);
}

/* Cards: outline — hard red frames, like an incident report for each story */
.diary-page [data-card="outline"] .diary-card-inner {
  padding: 1.25rem;
  border: 1px solid var(--accent);
  border-radius: 0;
  background: var(--paper);
  transition: transform 180ms ease;
}

.diary-page [data-card="outline"] .diary-card-inner:hover {
  transform: translateY(-2px);
}

.diary-page [data-card="outline"] .diary-card-title {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.2rem;
  line-height: 1.25;
  color: var(--ink);
}

.diary-page [data-card="outline"] .diary-card-body {
  color: var(--ink-soft);
  font-size: 1rem;
  line-height: 1.65;
}

/* Political news: tiles of hardened ground — the alliance crisis is the load-bearing wall */
.diary-page [data-card="tile"] .diary-card-inner {
  padding: 1.5rem;
  background: var(--paper-alt);
  border-left: 4px solid var(--accent);
}

.diary-page [data-card="tile"] .diary-card-title {
  font-family: var(--font-display);
  font-weight: 700;
  color: var(--ink);
}

.diary-page [data-card="tile"] .diary-card-body {
  color: var(--ink-soft);
}

/* Financial news: stat — the red number looms like a warning sign */
.diary-page [data-card="stat"] .diary-card-inner {
  border-top: 4px solid var(--accent);
  padding-top: 1rem;
}

.diary-page [data-card="stat"] .diary-card-figure {
  font-family: var(--font-display);
  font-weight: 800;
  color: var(--accent);
  font-size: clamp(2.75rem, 10cqi, 4.5rem);
  line-height: 0.95;
}

.diary-page [data-card="stat"] .diary-card-title {
  font-family: var(--font-display);
  font-weight: 700;
  color: var(--ink);
}

.diary-page [data-card="stat"] .diary-card-body {
  color: var(--ink-soft);
}

/* Tech news: banner — a red slab of outage, the digital world's blackout registered as a hard band */
.diary-page [data-card="banner"] .diary-card-inner {
  border: 1px solid var(--accent);
  gap: 0;
}

.diary-page [data-card="banner"] .diary-card-title {
  background: var(--accent);
  color: var(--accent-ink);
  padding: 0.6rem 1rem;
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.05rem;
  letter-spacing: 0.01em;
}

.diary-page [data-card="banner"] .diary-card-body {
  padding: 1.1rem;
  color: var(--ink-soft);
}

/* Entertainment: numbered — the news reads like a count of small reprieves in a red ledger */
.diary-page [data-card="numbered"] .diary-card-inner {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 0.35rem 1rem;
  align-content: start;
}

.diary-page [data-card="numbered"] .diary-card-index {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 2.2rem;
  line-height: 0.9;
  color: var(--accent);
  grid-row: 1 / span 4;
}

.diary-page [data-card="numbered"] .diary-card-title {
  font-family: var(--font-display);
  font-weight: 700;
  color: var(--ink);
}

.diary-page [data-card="numbered"] .diary-card-body {
  color: var(--ink-soft);
}

/* Music: plain — the only untouched element, a soft passage in a hard day */
.diary-page [data-section="music-releases"] .diary-card-inner {
  gap: 0.5rem;
}

.diary-page [data-section="music-releases"] .diary-card-title {
  font-family: var(--font-display);
  font-weight: 700;
  color: var(--ink);
}

.diary-page [data-section="music-releases"] .diary-card-body {
  color: var(--ink-soft);
}

/* Stock analysis: stat cards in a grid — red digits everywhere, the market's distress signal */
.diary-page [data-section="stock-analysis"] .diary-card-inner {
  border-top: 3px solid var(--accent);
  padding-top: 0.9rem;
}

.diary-page [data-section="stock-analysis"] .diary-card-figure {
  font-family: var(--font-display);
  font-weight: 800;
  color: var(--accent);
  font-size: clamp(2rem, 8cqi, 3rem);
}

.diary-page [data-section="stock-analysis"] .diary-card-title {
  font-family: var(--font-display);
  font-weight: 700;
  color: var(--ink);
  font-size: 1.1rem;
}

.diary-page [data-section="stock-analysis"] .diary-card-body {
  color: var(--ink-soft);
  font-size: 0.95rem;
}

/* Outlook: timeline — the days ahead hang off a red rail, each one a dot of risk */
.diary-page [data-card="timeline"] .diary-card-inner {
  padding-left: 1.75rem;
}

.diary-page [data-card="timeline"] .diary-card-inner::before {
  background: var(--accent);
  width: 1.5px;
}

.diary-page [data-card="timeline"] .diary-card-inner::after {
  background: var(--accent);
  box-shadow: 0 0 0 4px var(--paper);
}

.diary-page [data-card="timeline"] .diary-card-title {
  font-family: var(--font-display);
  font-weight: 700;
  color: var(--ink);
}

.diary-page [data-card="timeline"] .diary-card-body {
  color: var(--ink-soft);
}

/* Threads, figures, citations: keep every accent red and readable */
.diary-page .diary-card-thread {
  border-color: var(--accent);
  color: var(--accent);
}

.diary-page .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

.diary-page .diary-prose {
  color: var(--ink-soft);
}

.diary-page .diary-prose a {
  color: var(--accent);
}

.diary-page .diary-prose a:hover {
  color: var(--ink);
}

.diary-page .diary-prose strong {
  color: var(--ink);
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--accent);
  color: var(--ink);
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
}

.diary-page .diary-prose ol > li::marker {
  color: var(--accent);
}

.diary-page .diary-prose code,
.diary-page .diary-prose pre {
  background: var(--paper-alt);
  border-color: var(--rule);
}

/* Markets: the sparkline tiles carry the red of the day's slide */
.diary-page .diary-spark {
  background: var(--paper-alt);
  border-color: var(--rule);
}

.diary-page .diary-spark.is-down {
  color: var(--accent);
}

.diary-page .diary-spark.is-up {
  color: var(--ink);
}

.diary-page .diary-spark-value {
  color: var(--ink);
}

.diary-page .diary-markets-label {
  color: var(--muted);
}

/* Footer: a quiet red line ends the page */
.diary-page .diary-footer {
  border-top: 1px solid var(--accent);
  color: var(--muted);
}

.diary-page .diary-footer a {
  color: var(--ink);
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}

/* Drop cap: a red opening letter, struck with the day's gravity */
.diary-page .diary-section:first-child .diary-card--outline:first-child .diary-prose > p:first-of-type::first-letter {
  color: var(--accent);
  font-family: var(--font-display);
  font-weight: 800;
}
